new file mode 100644
index 0000000..38a803b
--- /dev/null
+++ b/.github/workflows/engine.yml
@@ -0,0 +1,63 @@
+name: Engine quality
+on:
+  push:
+    branches: [main]
+  pull_request:
+permissions:
+  contents: read
+concurrency:
+  group: engine-${{ github.ref }}
+  cancel-in-progress: true
+jobs:
+  engine:
+    runs-on: ubuntu-24.04
+    timeout-minutes: 45
+    steps:
+      - uses: actions/checkout@11bd71901bbe5b1630ceea73d27597364c9af683 # v4.2.2
+      - uses: actions/setup-node@49933ea5288caeca8642d1e84afbd3f7d6820020 # v4.4.0
+        with:
+          node-version: '24.21.0'
+          cache: npm
+      - name: Install pinned Rust toolchain
+        run: rustup toolchain install 1.95.0 --profile minimal --component rustfmt,clippy --target wasm32-unknown-unknown
+      - name: Native checks and host scheduling tests
+        run: |
+          cargo fmt --all --check
+          cargo xtask test
+          cargo test -p nir-presentation --locked
+          cargo clippy --locked --workspace --all-targets --exclude player-web --exclude nir-render-wgpu --exclude nir-platform-web -- -D warnings
+          cargo clippy --locked -p player-web --target wasm32-unknown-unknown -- -D warnings
+          npm ci
+          npm run test:host
+      - name: Build actual SDK and engine test project
+        run: |
+          cargo install wasm-bindgen-cli --version 0.2.100 --locked
+          cargo xtask sdk
+          ./dist/novelc -p examples/rain-letters resolve
+          ./dist/novelc -p examples/rain-letters check --locked
+          ./dist/novelc -p examples/rain-letters test
+          ./dist/novelc -p examples/rain-letters build --locked --out dist/rain-letters-web
+          python3 scripts/verify_release.py dist/rain-letters-web
+          python3 scripts/verify_sdk.py
+      - name: Install Chromium and system libraries
+        run: npx playwright install --with-deps chromium
+      - name: Chromium software WebGPU regression
+        env:
+          # Keep WebGPU and the compositor on compatible software Vulkan paths.
+          # Force X11 so a developer's Wayland session cannot bypass Xvfb.
+          NIR_CHROME_ARGS: >-
+            --ozone-platform=x11 --use-angle=swiftshader --enable-unsafe-swiftshader
+            --use-webgpu-adapter=swiftshader --enable-gpu --ignore-gpu-blocklist
+            --enable-features=Vulkan --use-vulkan=swiftshader
+        run: |
+          export CHROMIUM="$(node --input-type=module -e 'import { chromium } from "playwright"; console.log(chromium.executablePath())')"
+          mkdir -p target/tmp
+          TMPDIR="$PWD/target/tmp" xvfb-run -a -s '-screen 0 1920x1080x24' npm run test:browser -- --max-failures=1
+      - name: Retain test evidence
+        if: always()
+        uses: actions/upload-artifact@ea165f8d65b6e75b540449e92b4886f43607fa02 # v4.6.2
+        with:
+          name: engine-test-evidence
+          path: reports/
+          if-no-files-found: ignore
+          retention-days: 7
